// Shared transfer-tab flow used by transfer-tab.mjs and transfer-lost-response.mjs
import {
  BASE,
  startRecording,
  finishRecording,
  switchPerson,
  nav,
  beat,
  preClick,
} from './lib.mjs';

export async function runTransfer({ name, recipient, amount, description }) {
  const rec = await startRecording(name);
  const { page, mark } = rec;
  try {
    await page.goto(BASE, { waitUntil: 'networkidle' });
    mark('app loaded');
    await beat(page, 700);
    await switchPerson(page, 'Lucía');
    mark('person Lucía');
    await beat(page, 800);
    await nav(page, 'Transfers');
    await page.waitForSelector('.transfer-card.phase-draft');
    mark('transfers draft card');
    await beat(page, 1000);

    await preClick(page);
    await page.locator('.recipient-chip', { hasText: recipient }).first().click();
    mark(`recipient ${recipient}`);
    await beat(page, 700);
    const pills = await page.locator('.account-pill').count();
    if (pills) {
      await preClick(page);
      await page.locator('.account-pill').first().click();
      mark('account pill selected');
      await beat(page, 700);
    }

    const amountInput = page.locator('input[aria-label="Amount in euros"]');
    await amountInput.click();
    await amountInput.pressSequentially(amount, { delay: 160 });
    mark(`amount ${amount} typed`);
    await beat(page, 900);

    const descInput = page.locator('input[aria-label="Description"]');
    await descInput.click();
    await descInput.pressSequentially(description, { delay: 90 });
    mark('description typed');
    await beat(page, 800);

    await page.waitForSelector('button.transfer-submit:not([disabled])');
    await page.waitForFunction(
      () => getComputedStyle(document.querySelector('button.transfer-submit')).opacity === '1',
    );
    await preClick(page);
    await page.getByRole('button', { name: 'Review transfer' }).click();
    await page.waitForSelector('.transfer-card.phase-review');
    mark('review card (code + countdown)');
    await beat(page, 3000);

    await preClick(page);
    await page.getByRole('button', { name: 'Confirm transfer' }).click();
    await page.waitForSelector('.transfer-card.phase-done', { timeout: 60000 });
    const doneText = await page.locator('.transfer-card.phase-done').innerText();
    mark(`done card: ${doneText.includes('SENT') ? 'SENT' : 'not-sent'}`);
    console.log('DONE TEXT:', JSON.stringify(doneText.replace(/\n/g, ' | ')));
    await beat(page, 2500);
  } finally {
    const res = await finishRecording(rec, name);
    return res;
  }
}

import { scenario } from './lib.mjs';
import { runTransfer } from './transfer-flow.mjs';

console.log(scenario('normal'));
await runTransfer({
  name: 'transfer-tab',
  recipient: 'Carla',
  amount: '25',
  description: 'Team lunch',
});

import { scenario, sql, BANK_DB } from './lib.mjs';
import { runTransfer } from './transfer-flow.mjs';

console.log(scenario('lost-response'));
try {
  await runTransfer({
    name: 'transfer-lost-response',
    recipient: 'Bruno',
    amount: '10',
    description: 'Lost response check',
  });
  const ops = sql(
    BANK_DB,
    'SELECT reference, amountCents, status, createdAt FROM operations ORDER BY createdAt DESC LIMIT 3;',
  );
  console.log('LEDGER latest operations:\n' + ops);
} finally {
  console.log('restore scenario:', scenario('intermittent', 17));
}

import {
  BASE,
  startRecording,
  finishRecording,
  switchPerson,
  nav,
  newConversation,
  sendChat,
  waitForReply,
  lastBubble,
  beat,
  preClick,
} from './lib.mjs';

const NAME = 'chat-transfer-card';
const rec = await startRecording(NAME);
const { page, mark } = rec;
try {
  await page.goto(BASE, { waitUntil: 'networkidle' });
  mark('app loaded');
  await beat(page, 700);
  await switchPerson(page, 'Lucía');
  mark('person Lucía');
  await beat(page, 700);
  await nav(page, 'Assistant');
  mark('assistant tab');
  await beat(page, 900);

  let hasCard = false;
  for (const prompt of [
    'quiero mandarle 20 euros a Bruno',
    'quiero enviar dinero a Carla',
  ]) {
    await newConversation(page);
    mark('new conversation');
    await beat(page, 600);
    const before = await sendChat(page, prompt);
    mark(`sent "${prompt}"`);
    const cardAppears = page
      .waitForSelector('.chat-transfer .transfer-card.phase-draft', { timeout: 60000 })
      .then(() => true)
      .catch(() => false);
    await waitForReply(page, before, 60000).catch(() => {});
    hasCard = await cardAppears;
    if (!hasCard) {
      // card may render slightly after the bubble; give it a moment
      await page
        .waitForSelector('.chat-transfer .transfer-card.phase-draft', { timeout: 15000 })
        .then(() => (hasCard = true))
        .catch(() => {});
    }
    mark(`reply received, draft card=${hasCard}`);
    if (hasCard) break;
  }

  if (hasCard) {
    const amountInput = page.locator('.chat-transfer input[aria-label="Amount in euros"]');
    if (!(await amountInput.inputValue())) {
      await amountInput.click();
      await amountInput.pressSequentially('20', { delay: 160 });
      mark('amount filled');
    }
    const descInput = page.locator('.chat-transfer input[aria-label="Description"]');
    if (!(await descInput.inputValue())) {
      await descInput.click();
      await descInput.pressSequentially('Cena del viernes', { delay: 90 });
      mark('description filled');
    }
    await beat(page, 800);
    await page
      .waitForSelector('.chat-transfer button.transfer-submit:not([disabled])', {
        timeout: 10000,
      })
      .catch(() => {});
    await preClick(page);
    await page.locator('.chat-transfer button.transfer-submit').click();
    await page.waitForSelector('.chat-transfer .transfer-card.phase-review');
    mark('review card');
    await beat(page, 3000);
    await preClick(page);
    await page.locator('.chat-transfer .primary-button', { hasText: 'Confirm' }).click();
    await page.waitForSelector('.chat-transfer .transfer-card.phase-done', { timeout: 60000 });
    mark('done card (SENT)');
    await beat(page, 2500);
  } else {
    console.log('NO CARD: last reply:', JSON.stringify(await lastBubble(page)));
    await beat(page, 2000);
  }
} finally {
  await finishRecording(rec, NAME);
}

import {
  BASE,
  startRecording,
  finishRecording,
  switchPerson,
  nav,
  newConversation,
  sendChat,
  waitForReply,
  lastBubble,
  beat,
  preClick,
} from './lib.mjs';

const NAME = 'chat-code-confirmation';
const rec = await startRecording(NAME);
const { page, mark } = rec;
const replies = [];
try {
  await page.goto(BASE, { waitUntil: 'networkidle' });
  mark('app loaded');
  await beat(page, 700);
  await switchPerson(page, 'Lucía');
  await beat(page, 700);
  await nav(page, 'Assistant');
  await beat(page, 800);
  await newConversation(page);
  mark('new conversation');
  await beat(page, 600);

  let before = await sendChat(page, 'Send 5 euros to Bruno for coffee');
  mark('sent request');
  await waitForReply(page, before, 90000);
  replies.push(await lastBubble(page));
  mark(`reply 1: ${replies[0].slice(0, 80)}`);
  await beat(page, 1500);

  before = await sendChat(page, 'yes');
  mark('sent "yes"');
  await waitForReply(page, before, 90000);
  replies.push(await lastBubble(page));
  mark(`reply 2 (reject): ${replies[1].slice(0, 80)}`);
  await beat(page, 1200);

  // read the confirmation code: review card, composer placeholder, or bubble text
  let code = await page
    .locator('.chat-transfer .confirmation-code')
    .first()
    .innerText()
    .catch(() => null);
  if (!code) code = await page.locator('.confirmation-code').first().innerText().catch(() => null);
  if (!code) {
    const ph = await page
      .locator('textarea[aria-label="Message the assistant"]')
      .getAttribute('placeholder')
      .catch(() => '');
    code = ph?.match(/confirm\s+([A-Za-z0-9]+)/i)?.[1] ?? null;
  }
  if (!code) {
    const all = await page.locator('.message.assistant .bubble').allInnerTexts();
    code = all.join(' ').match(/confirm\s+([A-Za-z0-9]{4,})/i)?.[1] ?? null;
  }
  console.log('CONFIRM CODE:', code);
  if (!code) throw new Error('could not find confirmation code in DOM');
  mark(`code read: ${code}`);
  await beat(page, 800);

  before = await sendChat(page, `confirm ${code}`);
  mark(`sent "confirm ${code}"`);
  await waitForReply(page, before, 90000);
  replies.push(await lastBubble(page));
  mark(`reply 3 (done): ${replies[2].slice(0, 80)}`);
  await page
    .waitForSelector('.transfer-card.phase-done', { timeout: 15000 })
    .then(() => mark('card phase-done'))
    .catch(() => {});
  await beat(page, 2500);
} finally {
  console.log('ASSISTANT REPLIES:', JSON.stringify(replies, null, 2));
  await finishRecording(rec, NAME);
}

