import {
  BASE,
  startRecording,
  finishRecording,
  switchPerson,
  nav,
  newConversation,
  sendChat,
  waitForReply,
  lastBubble,
  beat,
} from './lib.mjs';

const NAME = 'agent-scope';
const rec = await startRecording(NAME);
const { page, mark } = rec;
const replies = [];
try {
  await page.goto(BASE, { waitUntil: 'networkidle' });
  mark('app loaded');
  await beat(page, 700);
