// Whisper word-level transcription for every vo mp3 -> assets/vo/<ID>.words.json
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const env = readFileSync(
  '/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/.env.local',
  'utf8',
);
const KEY = env.match(/OPENAI_API_KEY=(.+)/)?.[1]?.trim();
const VO = '/Users/miguelgarglez/Developer/hackathon-tdots/video-v2/hyperframes/assets/vo';
const IDS = ['E01', 'E02', 'E03', 'E04', 'E05', 'E06', 'E06B', 'E06C', 'E07', 'E07B', 'E08'];

for (const id of IDS) {
  const mp3 = path.join(VO, `${id}.mp3`);
  const form = new FormData();
  form.append('file', new Blob([readFileSync(mp3)]), `${id}.mp3`);
  form.append('model', 'whisper-1');
  form.append('response_format', 'verbose_json');
  form.append('timestamp_granularities[]', 'word');
  form.append('language', 'es');
  const res = await fetch('https://api.openai.com/v1/audio/transcriptions', {
    method: 'POST',
    headers: { Authorization: `Bearer ${KEY}` },
    body: form,
  });
  if (!res.ok) throw new Error(`${id}: ${res.status} ${await res.text()}`);
  const json = await res.json();
  const words = (json.words ?? []).map((w) => ({ w: w.word, s: w.start, e: w.end }));
  writeFileSync(path.join(VO, `${id}.words.json`), JSON.stringify(words));
  console.log(`${id}: ${words.length} words`);
}

