// Builds compositions/captions.html (burned-in captions) and ../../demo.es.srt
// from the whisper word files in assets/vo/<ID>.words.json.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const PROJ = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const VO = path.join(PROJ, 'assets', 'vo');
const SRT = '/Users/miguelgarglez/Developer/hackathon-tdots/video-v2/demo.es.srt';
const TOTAL = 516.358;

// scene id -> absolute start (same offsets as index.html audio clips)
const OFFSETS = {
  E01: 0,
  E02: 16.97,
  E03: 57.29,
  E04: 120.29,
  E05: 172.01,
  E06: 216.77,
  E06B: 285.17,
  E06C: 326.026,
  E07: 385.338,
  E07B: 448.05,
  E08: 483.698,
};

const ENDS_WITH_PUNCT = /[.?!…,:;]$/;

const groups = [];
for (const [id, off] of Object.entries(OFFSETS)) {
  const words = JSON.parse(readFileSync(path.join(VO, `${id}.words.json`), 'utf8'));
  let cur = [];
  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    cur.push(w);
    const next = words[i + 1];
    const pause = next ? next.s - w.e >= 0.35 : false;
    const finalPunct = ENDS_WITH_PUNCT.test(w.w.trim());
    if (cur.length >= 4 && (finalPunct || pause || cur.length >= 7 || !next)) {
      groups.push({ start: cur[0].s + off, end: cur[cur.length - 1].e + off, text: cur.map((x) => x.w).join(' ').trim() });
      cur = [];
    } else if (!next && cur.length) {
      groups.push({ start: cur[0].s + off, end: cur[cur.length - 1].e + off, text: cur.map((x) => x.w).join(' ').trim() });
      cur = [];
    }
  }
  if (cur.length) {
    groups.push({ start: cur[0].s + off, end: cur[cur.length - 1].e + off, text: cur.map((x) => x.w).join(' ').trim() });
  }
}
groups.sort((a, b) => a.start - b.start);
// one group visible at a time: trim overlap, enforce a minimal hold
for (let i = 0; i < groups.length - 1; i++) {
  if (groups[i].end > groups[i + 1].start) groups[i].end = groups[i + 1].start;
}
const clean = groups.filter((g) => g.end - g.start > 0.15 && g.text.length);
console.log(`${clean.length} caption groups`);

const html = `<!doctype html>
<html>
  <head>
    <meta charset="UTF-8" />
  </head>
  <body>
    <template>
      <style>
        #root {
          position: absolute;
          inset: 0;
          font-family:
            ui-sans-serif,
            system-ui,
            -apple-system,
            'Segoe UI',
            sans-serif;
        }
        .cap-line {
          position: absolute;
          left: 0;
          right: 0;
          top: 950px;
          display: flex;
          justify-content: center;
          pointer-events: none;
        }
        .cap-line span {
          display: inline-block;
          max-width: 1500px;
          background: rgba(31, 61, 53, 0.92);
          color: #f8f6ef;
          font-size: 38px;
          font-weight: 600;
          font-family: Inter, ui-sans-serif, system-ui, sans-serif;
          padding: 14px 28px;
          border-radius: 14px;
          text-align: center;
          line-height: 1.3;
        }
      </style>
      <div
        id="root"
        data-composition-id="captions"
        data-width="1920"
        data-height="1080"
        data-layout-allow-caption-zone
      >
        ${clean
          .map(
            (g, i) =>
              `<div class="cap-line" id="cap-${i}" style="opacity:0"><span>${g.text
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')}</span></div>`,
          )
          .join('\n        ')}
      </div>
      <script>
        const tl = gsap.timeline({ paused: true });
        const CAPS = ${JSON.stringify(clean.map((g) => ({ s: +g.start.toFixed(3), e: +g.end.toFixed(3) })))};
        CAPS.forEach((g, i) => {
          const el = document.getElementById('cap-' + i);
          tl.fromTo(el, { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.18, ease: 'power2.out' }, g.s);
          tl.to(el, { opacity: 0, duration: 0.12 }, g.e - 0.12);
          tl.set(el, { opacity: 0, visibility: 'hidden' }, g.e);
        });
        // self-lint: warn if a group is still visible past its window
        setTimeout(() => {
          CAPS.forEach((g, i) => {
            const el = document.getElementById('cap-' + i);
            if (getComputedStyle(el).opacity === '1' && tl.time() > g.e)
              console.warn('caption still visible past end:', i);
          });
        }, 0);
        window.__timelines['captions'] = tl;
      </script>
    </template>
  </body>
</html>
`;
writeFileSync(path.join(PROJ, 'compositions', 'captions.html'), html);

const ts = (t) => {
  const h = Math.floor(t / 3600),
    m = Math.floor((t % 3600) / 60),
    s = Math.floor(t % 60),
    ms = Math.round((t % 1) * 1000);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
};
