// from the whisper word files in assets/vo/<ID>.words.json.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const PROJ = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const VO = path.join(PROJ, 'assets', 'vo');
const SRT = '/Users/miguelgarglez/Developer/hackathon-tdots/video-v2/demo.es.srt';
const TOTAL = 516.358;

// scene id -> absolute start (same offsets as index.html audio clips)
const OFFSETS = {
  E01: 0,
  E02: 16.97,
  E03: 57.29,
  E04: 120.29,
  E05: 172.01,
  E06: 216.77,
  E06B: 285.17,
  E06C: 326.026,
  E07: 385.338,
  E07B: 448.05,
  E08: 483.698,
};

const ENDS_WITH_PUNCT = /[.?!…,:;]$/;

const groups = [];
for (const [id, off] of Object.entries(OFFSETS)) {
  const words = JSON.parse(readFileSync(path.join(VO, `${id}.words.json`), 'utf8'));
  let cur = [];
  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    cur.push(w);
    const next = words[i + 1];
    const pause = next ? next.s - w.e >= 0.35 : false;
    const finalPunct = ENDS_WITH_PUNCT.test(w.w.trim());
    if (cur.length >= 4 && (finalPunct || pause || cur.length >= 7 || !next)) {
      groups.push({ start: cur[0].s + off, end: cur[cur.length - 1].e + off, text: cur.map((x) => x.w).join(' ').trim() });
      cur = [];
    } else if (!next && cur.length) {
      groups.push({ start: cur[0].s + off, end: cur[cur.length - 1].e + off, text: cur.map((x) => x.w).join(' ').trim() });
      cur = [];
    }
  }
  if (cur.length) {
    groups.push({ start: cur[0].s + off, end: cur[cur.length - 1].e + off, text: cur.map((x) => x.w).join(' ').trim() });
  }
}
groups.sort((a, b) => a.start - b.start);
// one group visible at a time: trim overlap, enforce a minimal hold
for (let i = 0; i < groups.length - 1; i++) {
  if (groups[i].end > groups[i + 1].start) groups[i].end = groups[i + 1].start;
}
