console.log(`${clean.length} caption groups`);

const html = `<!doctype html>
<html>
  <head>
    <meta charset="UTF-8" />
  </head>
  <body>
    <template>
      <style>
        #root {
          position: absolute;
          inset: 0;
          font-family:
            ui-sans-serif,
            system-ui,
            -apple-system,
            'Segoe UI',
            sans-serif;
        }
        .cap-line {
          position: absolute;
          left: 0;
          right: 0;
          top: 950px;
          display: flex;
          justify-content: center;
          pointer-events: none;
        }
        .cap-line span {
          display: inline-block;
          max-width: 1500px;
          background: rgba(31, 61, 53, 0.92);
          color: #f8f6ef;
          font-size: 38px;
          font-weight: 600;
          font-family: ui-sans-serif, system-ui, sans-serif;
          padding: 14px 28px;
          border-radius: 14px;
          text-align: center;
          line-height: 1.3;
        }
      </style>
      <div
        id="root"
        data-composition-id="captions"
        data-width="1920"
        data-height="1080"
        data-layout-allow-caption-zone
      >
        ${clean
          .map(
            (g, i) =>
              `<div class="cap-line" id="cap-${i}" data-layout-allow-overlap style="opacity:0"><span>${g.text
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')}</span></div>`,
          )
          .join('\n        ')}
      </div>
      <script>
        const tl = gsap.timeline({ paused: true });
        const CAPS = ${JSON.stringify(clean.map((g) => ({ s: +g.start.toFixed(3), e: +g.end.toFixed(3) })))};
        CAPS.forEach((g, i) => {
          const el = document.getElementById('cap-' + i);
